    {% endif %}
    Chart.defaults.global.defaultFontColor = '{{ fontcolor }}';
    Chart.defaults.global.defaultFontFamily = "{{ fontfamily }}";
    var ctx = document.getElementById('chart-{{ id }}').getContext('2d');
