      type: 'box'
      , width: '{{chartwidth}}'
      , height: '{{chartheight}}'
      {%- if target != 'undefined' -%}, target: '{{target}}'{%- endif -%}
      {%- if yaxisminvalue != 'undefined' -%}, chartRangeMin: {{yaxisminvalue}}{%- endif -%}
      {%- if yaxismaxvalue != 'undefined' -%}, chartRangeMax: {{yaxismaxvalue}}{%- endif -%}
