      {%- if target != 'undefined' -%}, target: '{{target}}'{%- endif -%}
      , targetColor: '{{targetcolor}}'
      , chartRangeMin: {{yaxisminvalue}}
      , chartRangeMax: {{yaxismaxvalue}}
    });
  {%- endif -%}
{%- endcapture -%}

{%- if renderChart -%}
