{% endif %}

{% javascript id:'googlemapsvisualizationapi' url:'{{ "https://maps.googleapis.com/maps/api/js?libraries=visualization&key=" | Append:apiKey }}' %}{% endjavascript %}

{% stylesheet %}
.{{ id }} {
    width: {{ width }};
}

#map-container-{{ id }} {
    position: relative;
}

#{{ id }} {
    height: {{ height }};
    overflow: hidden;
    padding-bottom: 22.25%;
