{% if showrangeslider %}
{{ '/Scripts/ion.rangeSlider/css/ion.rangeSlider.Rock.css' | AddCssLink }}
<div class="form-group range-slider">
    <label class="control-label" for="{{ id }}_slider">Radius<a class="help" href="#" tabindex="-1" data-toggle="tooltip" data-placement="auto" data-container="body" data-html="true" title="The radius of influence for each data point, in pixels"><i class="fa fa-info-circle"></i></a></label> 
    <div class="control-wrapper">
        <input type="text" value="{{ radius | AsInteger }}" id="{{ id }}_slider" class="form-control" />
    </div>
</div>
{% endif %}


<div class="map-container {{ id }}">
    <div id="map-container-{{ id }}"></div>
	<div id="{{ id }}"></div>
</div>	


<script>
    // create javascript array of datapoints info
    var heatMapData = [
    {% for point in datapoints -%}
        {%- assign location = point.location | Split:',' -%}
        {location: new google.maps.LatLng({{ location[0] }}, {{ location[1] }}), weight:{{ point.weight | Default:'1' }}}{% unless forloop.last %},{% endunless %}
    {% endfor -%}
    ];

	//Set Map
	function initialize{{ id }}() {
        var bounds = new google.maps.LatLngBounds();

        {% if center != '' -%}
            {%- assign organizationAddress = 'Global' | Attribute:'OrganizationAddress','Object' -%}
            {%- assign center = organizationAddress.Latitude | Append:',' | Append:organizationAddress.Longitude -%}
        {% endif -%}
    	var centerLatlng = new google.maps.LatLng( {{ center }} );
    	
    	var mapOptions = {
    		{% if zoom != '' -%}
    		    zoom: {{ zoom }},
    		{% endif -%}
    		scrollwheel: {{ scrollwheel }},
    		draggable: {{ draggable }},
    		{% if center != '' -%}
    		    center: centerLatlng,
    		{% endif -%}
    		mapTypeId: '{{ maptype }}',
    		zoomControl: {{ showzoom }},
            mapTypeControl: {{ showmaptype }},
            gestureHandling: '{{ gesturehandling }}',
            streetViewControl: {{ showstreetview }},
            fullscreenControl: {{ showfullscreen }}
    		{% if style and style.content != "" %}
                ,styles: {{ style.content | StripNewlines | Trim }}
            {% endif %}
	    }

		var map = new google.maps.Map(document.getElementById('{{ id }}'), mapOptions);
		var heatmap = new google.maps.visualization.HeatmapLayer({
            data: heatMapData
        });
        heatmap.setMap(map);

        {% if showrangeslider %}
        // create & hook into rangeslider
        Rock.controls.rangeSlider.initialize({ controlId: '{{ id }}_slider', min: '1', max: '128', step:'1', from: '{{ radius | AsInteger }}', disable: false });
        var rangeSlider = $('#{{ id }}_slider');
        rangeSlider.on("change", function(obj) {
            var newRadius = parseInt($(this).val());
            if (heatmap) {
                heatmap.set('radius', newRadius);
            }
        });
        {% endif %}
        
		//Resize Function
		google.maps.event.addDomListener(window, "resize", function() {
			var center = map.getCenter();
			google.maps.event.trigger(map, "resize");
			map.setCenter(center);
		});
	}

    google.maps.event.addDomListener(window, 'load', initialize{{ id }});
</script>

{% if CurrentPerson %}
    {% assign entitytypeguid = entitytypeguid | Trim %}
    {% assign entityguid = entityguid | Trim %}
    {% assign entitytypeid = entitytypeid | Trim %}
    {% assign entityid = entityid | Trim %}
    {% if entitytypeguid != '' and entityguid != '' %}
    {% assign entitytype = entitytypeguid %}
    {% assign entity = entityguid %}
    {% else %}
    {% assign entitytype = entitytypeid %}
    {% assign entity = entityid %}
    {% endif %}
    {% assign purposekey = purposekey | Trim %}
    {% assign suppresswarnings = suppresswarnings | AsBoolean %}
    {% assign isfollowed = isfollowed | AsBoolean %}
    
    {% if entitytype != '' and entity != '' %}
        <div class="followicon js-followicon {% if isfollowed %}isfollowed{% endif %}" data-entitytype="{{ entitytype }}" data-entity="{{ entity }}" {% if purposekey != '' %}data-purpose-key="{{ purposekey }}"{% endif %} data-followed="{{ isfollowed }}">
            {{ blockContent }}
        </div>
    
        {% javascript id:'followicon' disableanonymousfunction:'true'%}
            $(document).ready(function() {
                // Use event delegation to bind the click event
                $(document).on('click', '.js-followicon', function(e) {
                    e.preventDefault();

                    var icon = $(this);
                    var entityType = icon.data('entitytype');
                    var entity = icon.data('entity');
                    var purpose = icon.data('purpose-key');
        
                    if (purpose) {
                        purpose = '?purposeKey=' + purpose;
                    } else {
                        purpose = '';
                    }
        
                    icon.toggleClass('isfollowed');
        
                    var actionType = icon.hasClass('isfollowed') ? 'POST' : 'DELETE';
        
                    $.ajax({
                        url: '/api/Followings/' + entityType + '/' + entity + purpose,
                        type: actionType,
                        statusCode: {
                            201: function() {
                                icon.attr('data-followed', 'true');
                            },
                            204: function() {
                                icon.attr('data-followed', 'false');
                            },
                            500: function() {
                                {% unless suppresswarnings %}
                                alert('Error: Check your Rock security settings and try again.');
                                {% endunless %}
                            }
                        },
                        error: function() {
                            icon.toggleClass('isfollowed');
                        }
                    });
                });
            });
        {% endjavascript %}
    {% else %}
        <!-- Follow Icon Shortcode is missing entitytype and/or entity. Note: Guids or Ids must be provided  -->
    {% endif %}
{% endif %}

//- Prep configuration settings
{% assign sc-statusList = campusstatuses | Split:',' %}
{% assign sc-typeList = campustypes | Split:',',true %}
{% assign sc-selectableList = selectablecampuses | Split:',' %}
{% assign sc-currentValues = value | Split:',' %} //- Note we're supporting the possibility that there could be multiple values.
{% assign includeinactive = includeinactive | AsBoolean %}
{% assign allowmultiple = allowmultiple | AsBoolean %}

//- Get source data
{% assign sc-campuses = 'All' | FromCache:'Campus'  %}

//- Filtering works by selecting all campuses that should not be shown
//- and then removing them from the list. This means that configuration
//- filters are AND not OR (which matches the C# logic).

//- Filter by type
{% if sc-typeList != empty %}

    {% for campus in sc-campuses reversed %}
        {% assign campusTypeId = campus.CampusTypeValueId | ToString %}
        {% assign isConfiguredType = sc-typeList | Contains:campusTypeId %}
        {% if isConfiguredType == false %}
            {% assign sc-campuses = sc-campuses | RemoveFromArray:campus %}
        {% endif %}
    {% endfor %}

{% endif %}

//- Filter by status
{% if sc-statusList != empty %}

    {% for campus in sc-campuses reversed %}
        {% assign campusStatusId = campus.CampusStatusValueId | ToString %}
        {% assign isConfiguredStatus = sc-statusList | Contains:campusStatusId %}
        {% if isConfiguredStatus == false %}
            {% assign sc-campuses = sc-campuses | RemoveFromArray:campus %}
        {% endif %}
    {% endfor %}

{% endif %}

//- Filter by selected
{% if sc-selectableList != empty %}

    {% for campus in sc-campuses reversed %}
        {% assign campusId = campus.Id | ToString %}
        {% assign isSelected = sc-selectableList | Contains:campusId %}
        {% if isSelected == false %}
            {% assign sc-campuses = sc-campuses | RemoveFromArray:campus %}
        {% endif %}
    {% endfor %}

{% endif %}

//- Remove inactive campuses
{% if includeinactive == false %}
    {% assign sc-campuses = sc-campuses | Where:'IsActive',true %}
{% endif %}

//- Ensure current values are still in the list, the value can be either a campus id or guid
{% assign allCampuses = 'All' | FromCache:'Campus'  %}
{% for currentValue in sc-currentValues %}
    {% for campus in allCampuses %}
        {% assign campusId = campus.Id | ToString %}
        {% assign campusGuid = campus.Guid | ToString %}
        {% if campusId == currentValue or campusGuid == currentValue %}
            //- Ensure the campus list has this campus, if not add it
            {% assign isInCampusList = sc-campuses | Contains:campus %}

            {% if isInCampusList == false %}
                {% assign sc-campuses = sc-campuses | AddToArray:campus %}
            {% endif %}
        {% endif %}
    {% endfor %}
{% endfor %}

//- Sort Campuses
{% assign sc-campuses = sc-campuses | OrderBy:'Order' %}

//- Control formatting
{% if allowmultiple %}
    {[ checkboxlist label:'{{ label }}' showlabel:'{{ showlabel }}' name:'{{ name }}' isrequired:'{{ isrequired }}' value:'{{ value }}' columns:'4' controltype:'campus-picker' id:'{{ id }}' validationmessage:'{{ validationmessage }}' additionalattributes:'{{ additionalattributes}}' ]}

        {% for campus in sc-campuses %}
            [[ item value:'{% if valuefield == 'id' %}{{ campus.Id }}{% else %}{{ campus.Guid }}{% endif %}' text:'{{ campus.Name }}' ]][[ enditem]]
        {% endfor %}

    {[ endcheckboxlist ]}
{% else %}
    {[ dropdown label:'{{ label }}' showlabel:'{{ showlabel }}' name:'{{ name }}' longlistenabled:'{{ longlistenabled }}' value:'{{ value }}' controltype:'campus-picker' isrequired:'{{ isrequired }}' id:'{{ id }}' validationmessage:'{{ validationmessage }}' additionalattributes:'{{ additionalattributes}}' ]}

        {% for campus in sc-campuses %}
            [[ item value:'{% if valuefield == 'id' %}{{ campus.Id }}{% else %}{{ campus.Guid }}{% endif %}' text:'{{ campus.Name }}' ]][[ enditem]]
        {% endfor %}

    {[ enddropdown ]}
{% endif %}

{% assign isrequired = isrequired | AsBoolean %}
{% assign sc-values =  value | Split:',',true %}

